```hcl
resource "aws_bedrock_custom_model" "example_resource" {
  custom_model_name     = "example-custom-model"
  job_name              = "example-customization-job"
  base_model_identifier = "arn:aws:bedrock:us-east-1::foundation-model/amazon.titan-text-express-v1"
  role_arn              = "arn:aws:iam::123456789012:role/example-bedrock-customization-role"
  custom_model_kms_key_id = "arn:aws:kms:us-east-1:123456789012:key/example-key-id" # Critical: without this the model is encrypted with an AWS owned key

  hyperparameters = {
    epochCount = "1"
  }

  output_data_config {
    s3_uri = "s3://example-bucket/output/"
  }

  training_data_config {
    s3_uri = "s3://example-bucket/training/"
  }
}
```

