```hcl
resource "awscc_bedrock_guardrail" "example_resource" {
  name                      = "example-guardrail"
  blocked_input_messaging   = "Sorry, I cannot answer that."
  blocked_outputs_messaging = "Sorry, I cannot answer that."

  contextual_grounding_policy_config = {
    filters_config = [
      {
        type      = "GROUNDING"
        threshold = 0.75 # Critical: 0 can never be tripped
        action    = "BLOCK"  # Critical: NONE scores without blocking
        enabled   = true     # Critical: when false the evaluation never runs
      },
      {
        type      = "RELEVANCE"
        threshold = 0.75
        action    = "BLOCK"
        enabled   = true
      },
    ]
  }
}
```

