```hcl
# Terraform: enable S3 object-level READ data events for all buckets on a trail
resource "aws_cloudtrail" "<example_resource_name>" {
  name           = "<example_resource_name>"
  s3_bucket_name = "<example_resource_name>"

  event_selector {
    read_write_type = "ReadOnly"                 # CRITICAL: log read-only data events
    data_resource {
      type   = "AWS::S3::Object"                 # CRITICAL: target S3 object-level events
      values = ["arn:aws:s3"]                    # CRITICAL: apply to all S3 buckets/objects
    }
  }
}
```

```hcl
resource "aws_cloudtrail" "<example_resource_name>" {
  name           = "<example_resource_name>"
  s3_bucket_name = "<example_resource_name>"

  event_selector {
    read_write_type = "WriteOnly"
    data_resource {
      type   = "AWS::S3::Object"
      values = ["arn:aws:s3"]  # Critical: logs S3 object-level write events for all buckets to pass the check
    }
  }
}
```

```hcl
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name                 = "<example_resource_name>"
  deletion_protection  = "ACTIVE" # Critical: Enables deletion protection to prevent accidental pool deletion
}
```

```hcl
# Terraform: Require MFA and enable TOTP
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name              = "<example_resource_name>"
  mfa_configuration = "ON" # Critical: sets MFA to required

  software_token_mfa_configuration {
    enabled = true # Critical: enables TOTP so ON is valid
  }
}
```

```hcl
resource "aws_cognito_user_pool" "pool" {
  name = "<example_resource_name>"

  password_policy {
    require_lowercase = true  # Critical: enforces at least one lowercase character
  }
}
```

```hcl
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name = "<example_resource_name>"

  password_policy {
    minimum_length = 14  # Critical: enforce min length >=14 to pass the check
  }
}
```

```hcl
# Terraform: Enable number requirement in Cognito password policy
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name = "<example_resource_name>"

  password_policy {
    require_numbers = true  # Critical: enforces at least one numeric character in passwords
  }
}
```

```hcl
# Terraform: ensure Cognito User Pool requires at least one symbol in passwords
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name = "<example_resource_name>"

  password_policy {
    require_symbols = true  # Critical: enforce at least one symbol to pass the check
  }
}
```

```hcl
# Require uppercase in Cognito User Pool password policy
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name = "<example_resource_name>"

  password_policy {
    require_uppercase = true  # Critical: enforce at least one uppercase letter
  }
}
```

```hcl
# Terraform: Disable self-registration in a Cognito User Pool
resource "aws_cognito_user_pool" "<example_resource_name>" {
  admin_create_user_config {
    allow_admin_create_user_only = true  # Critical: disables self sign-up; only admins can create users
  }
}
```

```hcl
# Terraform: Set Cognito temporary password expiration to 7 days or less
resource "aws_cognito_user_pool" "<example_resource_name>" {
  name = "<example_resource_name>"

  password_policy {
    temporary_password_validity_days = 7  # Critical: 7 or less to pass the check
  }
}
```

```hcl
resource "aws_iam_service_linked_role" "example_resource" {
  aws_service_name = "config.amazonaws.com"
}

resource "aws_config_configuration_recorder" "example_resource" {
  name     = "example_resource"
  role_arn = aws_iam_service_linked_role.example_resource.arn
}

resource "aws_config_delivery_channel" "example_resource" {
